    try:
        hn_json = json.loads(hn_data)
        for hit in hn_json.get('hits', []):
            title = hit.get('title', '')
            url = hit.get('url', f"https://news.ycombinator.com/item?id={hit.get('objectID')}")
            author = hit.get('author', '')
            points = hit.get('points', 0)
            created = hit.get('created_at', '')[:10]
            if title and points > 5:
                results["技术突破"].append(f"[{title}]({url}) [HN-{points}pts, {author}]")
    except Exception as e:
        print(f"HN parse error: {e}")

# 2. Google News EN - AI RSS
